INSERT INTO `chat_history` VALUES (1,1,'What is a solution?','A solution (محلول) is a homogeneous mixture where one substance (the solute) is dissolved in another substance (the solvent). In a solution, the solute particles are evenly distributed throughout the solvent, resulting in a uniform composition. For example, when salt (the solute) is dissolved in water (the solvent), it forms a saline solution. Solutions can be in different states, such as solid, liquid, or gas.','2026-11-05 07:56:13'),(2,1,'hi how are you','This question is outside the Grade 8 Science curriculum. I can only help with science topics from your textbook. Try asking about the nature of science (طبيعة العلم) or energy transformations (الطاقة وتحولاتها).','2026-11-09 07:39:41'),(3,1,'Hello! How are you?','Hello and welcome! I\'m doing great, thank you! I\'m excited to help you with Grade 8 Science. Which topic or chapter would you like to explore today?','2026-11-09 08:45:28'),(4,1,'hi how are you','Hello and welcome! I\'m doing great, thank you! I\'m here to help you with Grade 8 Science. What topic or chapter would you like to explore today?','2026-11-09 08:48:50'),(5,1,'how\'s the day today','I\'m glad you asked! Every day is a great day for learning science! How about you? Are you ready to dive into some interesting concepts from your Grade 8 Science textbook? Let me know what you\'d like to discuss!','2026-11-09 08:49:11'),(6,1,'hi how are you','Hello and welcome! I\'m doing great, thank you! I\'m here to help you with Grade 8 Science. What topic or chapter would you like to explore today?','2026-11-16 06:14:37'),(7,2,'hi how are you','Hello and welcome! I\'m doing great, thank you! I\'m here to help you with Grade 8 Science. What topic or chapter would you like to explore today?','2026-11-19 11:43:28'),(8,1,'hi','Hello and welcome! I\'m your Grade 8 Science tutor. How can I assist you with your science studies today? Is there a specific topic or chapter you\'d like to explore?','2026-11-22 12:43:24');
/*!40000 ALTER TABLE `chat_history` ENABLE KEYS */;
