  `chapter` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lesson` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_suitable_for_questions` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT 'YES',
  `suitability_reason` text COLLATE utf8mb4_unicode_ci,
  `short_question` text COLLATE utf8mb4_unicode_ci,
  `short_answer` text COLLATE utf8mb4_unicode_ci,
  `mcq_question` text COLLATE utf8mb4_unicode_ci,
  `mcq_options` json DEFAULT NULL,
  `mcq_correct` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mcq_explanation` text COLLATE utf8mb4_unicode_ci,
  `reasoning_question` text COLLATE utf8mb4_unicode_ci,
  `reasoning_answer` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=82 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
